    /// <summary>
    /// MET Purchase order confirmation send email
    /// </summary>
    /// <param name="printer"></param>
    /// <param name="dataContract"></param>
    /// <param name="paramArray"></param>
    /// <param name="result"></param>
    [SubscribesTo(classStr(SRSPrintDestinationSettingsDelegates), delegateStr(SRSPrintDestinationSettingsDelegates, toEmail))]
    public static void SRSPrintDestinationSettingsDelegates_toEmail(SrsReportRunPrinter printer, SrsReportDataContract dataContract, Microsoft.Dynamics.AX.Framework.Reporting.Shared.ReportingService.ParameterValue[] paramArray, EventHandlerResult result)
    {
        SrsReportDataContract   metContract = dataContract;
        boolean                 sendEmail   = true;
        RefRecId                metPurchTableRecId;
        /* VM - CB219 - PO Acknowledgement remove fields
        
        if(metContract && metContract.parmRdpContract() as PurchPurchaseOrderContract)
        {
            PurchPurchaseOrderContract metPurchConfirmContract  = metContract.parmRdpContract() as PurchPurchaseOrderContract;
            
            VendPurchOrderJour  metVendPurchOrderJourStd;
            PurchTable          metpurchTableStd;
            METPurchTable       metPurchTable;

            select firstonly PurchId
                from metVendPurchOrderJourStd
                    where metVendPurchOrderJourStd.RecId == metPurchConfirmContract.parmRecordId()
                join recid
                from metpurchTableStd
                    where metpurchTableStd.PurchId == metVendPurchOrderJourStd.PurchId
                join POSubMode, POChngSubMode
                from metpurchTable
                    where metPurchTable.PurchTable == metpurchTableStd.Recid;

            metPurchTableRecId = metpurchTableStd.RecId;
            
            if(metPurchTableRecId && METVendSiteSettingsSetup::existsPOVendSiteRecord(metVendPurchOrderJourStd.PurchId))
            {
                if(VendPurchOrderJour::metIsFirstConfirmation(metVendPurchOrderJourStd.PurchId))
                {
                    if(metPurchTable.POSubMode)
                    {
                        if(!strContains(metPurchTable.POSubMode, METConstants::Email))
                        {
                            sendEmail = false;
                            metpurchTable.updatePOSentFlag();
                        }
                    }
                    else
                    {
                        sendEmail = false;
                        throw error("@MET:METPOSubModeErrorMsg");
                    }
                }
                else
                {
                    if(metPurchTable.POChngSubMode)
                    {
                        if(!strContains(metPurchTable.POChngSubMode, METConstants::Email))
                        {
                            sendEmail = false;
                            metpurchTable.updatePOSentFlag();
                        }
                    }
                    else
                    {
                        sendEmail = false;
                        throw error("@MET:METPOSubModeErrorMsg");
                    }
                }
            }
            */
            result.result(sendEmail);
    }
